const money=n=>'$'+n.toFixed(2);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=s=>document.querySelector(s);
let cart=JSON.parse(localStorage.getItem('kadibia-cart')||'[]');
let selection={color:'',size:'',quantity:1};
let shopState={category:'All',sort:'featured',query:''};
function saveCart(){localStorage.setItem('kadibia-cart',JSON.stringify(cart));updateCart()}
function count(){return cart.reduce((a,i)=>a+i.qty,0)}
function subtotal(){return cart.reduce((a,i)=>a+i.qty*(products.find(p=>p.id===i.id)?.price||0),0)}
function itemKey(i){return [i.id,i.color,i.size].join('|')}
function addItem(id,color,size,qty){let key=itemKey({id,color,size}),found=cart.find(i=>itemKey(i)===key);if(found)found.qty+=qty;else cart.push({id,color,size,qty});saveCart();openCart();toast('Added to your bag')}
function buyLink(id){return (typeof STRIPE_LINKS!=='undefined'&&STRIPE_LINKS[id])?STRIPE_LINKS[id]:'#'}
function stripeSetupDone(id){return buyLink(id).indexOf('REPLACE_ME')===-1}

/* ------------------------------- HOME PAGE ------------------------------ */
function card(p){return `<a class="product-card" href="${BASE}/product/${p.id}"><div class="photo"><img src="${p.images[0]}" alt="${p.sample?('Sample image for '+esc(p.name)):esc(p.name)}" loading="lazy">${p.tag?`<span class="tag">${p.tag}</span>`:''}</div><div class="card-meta"><div><h3>${esc(p.name)}</h3><p class="category">${p.category}${p.sample?' · Sample product':''}</p></div><span class="price">${money(p.price)}</span></div></a>`}
function home(){return `<section class="hero"><div class="hero-copy"><span class="eyebrow">NEW ARRIVAL</span><h1>Seamless Push-Up Leggings</h1><p>Seamless, stretchy, and comfortable — leggings that move with you from workout to weekend. Yours for $31, with free US shipping.</p><div><a href="${BASE}/product/seamless-push-up-leggings" class="btn">Shop now — $31.00</a></div></div><img class="hero-img" src="${BASE}/images/seamless-leggings-brown.jpg" alt="Seamless Push-Up Leggings in brown"></section><div class="trust"><div class="trust-item"><span class="trust-icon">♢</span><span><strong>Free US shipping</strong><small>On every order</small></span></div><div class="trust-item"><span class="trust-icon">↺</span><span><strong>30-day easy returns</strong><small>Unused items, no hassle</small></span></div><div class="trust-item"><span class="trust-icon">♧</span><span><strong>Secure checkout</strong><small>Powered by Stripe</small></span></div></div><section class="container section"><div class="section-head"><div><span class="eyebrow">FRESH IN</span><h2>Featured favorites</h2><p>Our first arrival — more of the collection is on its way.</p></div><a class="text-link" href="${BASE}/shop">Shop all products</a></div><div class="product-grid">${products.slice(0,4).map(card).join('')}</div></section><section class="story-band"><img src="${BASE}/images/seamless-leggings-detail.jpg" alt="Close-up of the seamless high waistband"><div class="story-copy"><span class="eyebrow">OUR PROMISE</span><h2>One product, done right.</h2><p>We're starting Kadibia the honest way: with a single product we believe in. A seamless knit made from stretchy nylon and elastane — made for workouts, weekends, and everything between.</p><p>Every order is prepared just for you by our trusted fulfillment partner and shipped straight to your door. No warehouse, no clutter, no gimmicks.</p><div><a class="text-link" href="${BASE}/product/seamless-push-up-leggings">Meet the leggings</a></div></div></div></section><section class="newsletter-band"><span class="eyebrow">NOTES FROM KADIBIA</span><h2>A little good in your inbox.</h2><p>Be first to hear about new arrivals and subscriber-only offers.</p><!-- NEWSLETTER SIGNUP — same free options as the footer form: paste your Mailchimp embedded-form action URL or Formspree endpoint into action="" below. --><form class="newsletter" id="home-newsletter" action="https://formsubmit.co/chikadibia17@gmail.com" method="POST"><label class="sr-only" for="home-email">Email address</label><input id="home-email" name="email" type="email" placeholder="Your email address" required><button>Sign me up</button></form></section>`}

/* -------------------------------- SHOP PAGE ----------------------------- */
function shop(){let cats=['All',...new Set(products.map(p=>p.category))];return `<div class="page-hero"><span class="eyebrow">THE COLLECTION</span><h1>Shop all</h1><p>Seamless comfort, made to move. Our first arrival is here — more of the collection is on its way.</p></div><section class="container section" style="padding-top:10px"><div class="shop-tools"><div class="filters" aria-label="Filter by category">${cats.map(c=>`<button data-filter="${c}" class="${shopState.category===c?'active':''}">${c}</button>`).join('')}</div><div class="sort-search"><input id="shop-search" type="search" placeholder="Search products" aria-label="Search products" value="${esc(shopState.query)}"><select id="shop-sort" aria-label="Sort products"><option value="featured">Featured</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option><option value="name">Name: A to Z</option></select></div></div><div id="shop-results"></div></section>`}
function renderShopResults(){let items=products.filter(p=>(shopState.category==='All'||p.category===shopState.category)&&p.name.toLowerCase().includes(shopState.query.toLowerCase()));if(shopState.sort==='price-low')items.sort((a,b)=>a.price-b.price);if(shopState.sort==='price-high')items.sort((a,b)=>b.price-a.price);if(shopState.sort==='name')items.sort((a,b)=>a.name.localeCompare(b.name));$('#shop-results').innerHTML=`<p class="shop-count">${items.length} product${items.length===1?'':'s'}</p>${items.length?`<div class="product-grid">${items.map(card).join('')}</div>`:'<div class="empty">No products match your search. Try a different term.</div>'}`}

/* ------------------------------ PRODUCT PAGE ---------------------------- */
const COLOR_HEX={'Brown':'#8a5a3b','Black':'#1c1c1c','Dark Gray':'#55534e','Khaki':'#c9b895','Light Gray':'#d8d8d8','Champagne':'#f1e3c8','Blue':'#6fa8dc','Deep Blue':'#27436b','Gray':'#8a8d91','Pink':'#f4b8c1','Red':'#b03a2e'};
function productPage(p){selection={color:p.colors[0],size:p.sizes[0],quantity:1};return `<section class="container product-layout"><div data-gallery="${p.id}"><div class="gallery-main"><img id="main-image" src="${p.images[0]}" alt="${p.sample?('Sample image for '+esc(p.name)):esc(p.name)}"></div><div class="thumbs">${p.images.map((im,i)=>`<button data-image="${i}" class="${i===0?'active':''}" aria-label="View image ${i+1}"><img src="${im}" alt=""></button>`).join('')}</div></div><div class="product-info"><span class="eyebrow">${p.category.toUpperCase()}${p.sample?' · SAMPLE PRODUCT':''}</span><h1>${esc(p.name)}</h1><div class="big-price">${money(p.price)}</div><p class="intro">${esc(p.description)}</p><div class="option-group"><span class="option-label">Color: <span id="selected-color">${p.colors[0]}</span></span><div class="swatches">${p.colors.map((v,i)=>`<button class="swatch${i===0?' active':''}" data-option="color" data-value="${v}" style="background:${COLOR_HEX[v]||'#ddd'}" aria-label="${v}" title="${v}"></button>`).join('')}</div></div><div class="option-group"><span class="option-label">Size: <span id="selected-size">${p.sizes[0]}</span></span>${p.sizes.map((v,i)=>`<button data-option="size" data-value="${v}" class="${i===0?'active':''}">${v}</button>`).join('')}</div><span class="option-label">Quantity</span><div class="purchase-row"><div class="stepper"><button data-product-qty="-1" aria-label="Decrease quantity">−</button><span id="product-qty">1</span><button data-product-qty="1" aria-label="Increase quantity">+</button></div><button class="btn" id="add-to-cart" data-id="${p.id}">Add to bag</button></div>${stripeSetupDone(p.id)?`<a class="btn outline full" href="${buyLink(p.id)}" target="_blank" rel="noopener">Buy now with Stripe — ${money(p.price)}</a>`:`<span class="btn outline full" aria-disabled="true" style="opacity:.55;pointer-events:none">Available soon</span>`}<p class="security-note">♢ Free US shipping · ↺ 30-day returns · Secure payment via Stripe</p><div class="tabs"><details open><summary>Description</summary><p>${esc(p.description)}</p></details><details><summary>Details &amp; care</summary><p>${p.sample?'Sample specifications. Replace with accurate materials, dimensions, and care instructions before launch.':(p.details?esc(p.details):'Seamless nylon-elastane knit. Machine wash cold, hang dry.')}</p></details><details><summary>Shipping &amp; returns</summary><p>Orders typically arrive in 7–15 business days. See our <a class="text-link" href="${BASE}/shipping-returns">shipping &amp; returns policy</a> for full details.</p></details><details><summary>Reviews</summary><p>${p.sample?'No reviews yet — this is a sample product. Real customer reviews will appear here after launch.':'No reviews yet — yours could be the first!'}</p></details></div></div></section>${(()=>{const others=products.filter(x=>x.id!==p.id).slice(0,4);return others.length?`<section class="container section" style="padding-top:0"><div class="section-head"><h2>You may also like</h2></div><div class="product-grid">${others.map(card).join('')}</div></section>`:''})()}`}

/* ------------------------------ STATIC PAGES ---------------------------- */
function pageHero(kicker,title,sub=''){return `<div class="page-hero"><span class="eyebrow">${kicker}</span><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>`}

function about(){return pageHero('OUR STORY','Meet Kadibia','Seamless activewear that moves with you.')+`<article class="content"><h2>Why Kadibia exists</h2><p>Kadibia started with a simple frustration: activewear that's either cheap and uncomfortable, or beautiful but overpriced. We believed there was room for something better — pieces that are genuinely comfortable, honestly described, and priced so real people can actually enjoy them.</p><div class="founder"><img src="${BASE}/images/founder.jpg" alt="Chikadibia, founder of Kadibia"><div><span class="eyebrow">MEET THE FOUNDER</span><h2>Hi, I'm Chikadibia.</h2><p>I started Kadibia with a simple belief: activewear should be comfortable, honestly described, and fairly priced. No inflated claims, no gimmicks — just pieces I'd happily recommend to my own family. Thanks for being part of the beginning.</p></div></div><h2>Our promise</h2><p>We're starting with one product done right: seamless leggings with a comfortable fit and a stretchy knit. As Kadibia grows, every new piece will earn its place the same way — comfortable, well made, and fairly priced.</p><p>One promise covers it all: if it carries the Kadibia name, it's something we'd happily wear ourselves.</p><h2>How we fulfill your order</h2><p>We don't keep a warehouse of inventory. Instead, your order is prepared by our trusted fulfillment partner and shipped straight to your door. It means less waste and no dusty stock — though it does mean delivery takes a little longer than the next-day giants. We think the trade is worth it, and our <a class="text-link" href="${BASE}/shipping-returns">shipping policy</a> tells you exactly what to expect.</p><h2>What we care about</h2><p>Honest descriptions. Fair prices. Helpful, human service when you need it. We follow US product-labeling rules for the categories we sell, including fiber-content and care information where required. If something ever falls short, our <a class="text-link" href="${BASE}/shipping-returns">30-day returns</a> have you covered.</p><div style="margin-top:30px"><a class="btn" href="${BASE}/shop">Explore the collection</a></div></article>`}

function faq(){return pageHero('HELP CENTER','Frequently asked questions','Real answers about ordering from Kadibia.')+`<div class="content">${[['How long will my order take to arrive?','Most US orders arrive within 7–15 business days. Here\'s the breakdown: we prepare and hand your order to the carrier within 1–3 business days, and delivery usually takes another 5–12 business days after that. You\'ll get a tracking link by email as soon as your order ships.'],['Where do you ship?','We currently ship within the United States, and shipping is free on every order.'],['How does checkout work? Is it secure?','When you\'re ready to buy, each "Buy now" button takes you to Stripe\'s secure checkout page. Your card details go directly to Stripe, and we never see or store your card number.'],['Can I change or cancel my order?','Because your order is prepared by our fulfillment partner shortly after you order, please contact us within 24 hours of ordering if you need a change or cancellation — we\'ll do our best. After that window the order may already be on its way and can no longer be changed.'],['What is your return policy?','You have 30 days from delivery to request a return on unused, undamaged items in their original packaging. See our full <a class="text-link" href="'+BASE+'/shipping-returns">shipping & returns policy</a> for the step-by-step process.'],['How do I track my order?','As soon as your order ships, we\'ll email you a tracking link. If it hasn\'t arrived within 15 business days of that email, contact us and we\'ll make it right.'],['Do you offer discounts or sales?','Join our newsletter for subscriber-only offers and first dibs on new arrivals — we\'d rather reward our regulars than play pricing games.'],['Is my personal information safe?','We limit collection to what the store needs, we never sell your data, and payments are processed by Stripe. Read our full <a class="text-link" href="'+BASE+'/privacy">privacy policy</a>.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>`}

function shipping(){return pageHero('HERE TO HELP','Shipping & returns','Last updated: September 29, 2026. Kadibia ("we", "us"). Contact: chikadibia17@gmail.com.')+`<article class="content"><h2>How fulfillment works</h2><p>We don't hold inventory in a warehouse. Your order is prepared by our trusted fulfillment partner and shipped directly to you — which means delivery takes a little longer than next-day retailers.</p><h2>Shipping</h2><ul><li><strong>Where we ship:</strong> United States only, at this time.</li><li><strong>Processing time:</strong> 1–3 business days before your order ships.</li><li><strong>Delivery time:</strong> typically 5–12 business days after shipping — so most orders arrive within <strong>7–15 business days</strong> of placing your order.</li><li><strong>Shipping cost:</strong> FREE on all US orders. No minimum, no surprises.</li><li><strong>Tracking:</strong> you'll receive a tracking link by email as soon as your order ships.</li></ul><p>Delivery estimates are not guarantees. Weather, carrier delays, and peak holiday volume can add time — we'll always keep you posted if something runs late.</p><h2>Returns &amp; refund policy</h2><ul><li><strong>Window:</strong> request a return within <strong>30 days of delivery</strong>.</li><li><strong>Condition:</strong> items must be unused, undamaged, and in original packaging.</li><li><strong>How to start:</strong> email chikadibia17@gmail.com with your order number and photos of the item. We'll reply with return instructions within 2 business days.</li><li><strong>Return shipping:</strong> customers cover return postage unless the item arrived damaged, defective, or wrong.</li><li><strong>Refunds:</strong> issued to your original payment method within 10 business days of us receiving your return.</li></ul><h2>Damaged or wrong items</h2><p>Send a photo to chikadibia17@gmail.com within 14 days of delivery and we'll make it right with a replacement or full refund — no need to ship anything back.</p><h2>Questions?</h2><p>Visit our <a class="text-link" href="${BASE}/contact">contact page</a> — a real human replies within 2 business days.</p></article>`}

function privacy(){return pageHero('LEGAL','Privacy policy','Last updated: September 29, 2026. Kadibia ("we", "us"). Contact: chikadibia17@gmail.com.')+`<article class="content"><h2>Who we are</h2><p><strong>Business name:</strong> Kadibia<br><strong>Address:</strong> 1212 Silliman Ave, Erie, PA, USA<br><strong>Contact:</strong> chikadibia17@gmail.com<br><strong>Where we sell:</strong> United States only.</p><h2>What we collect</h2><p>We collect only what we need to run the store:</p><ul><li><strong>Order information</strong> — your name, email, shipping address, and what you bought, so we can fulfill your order and contact you about it.</li><li><strong>Payment information</strong> — processed securely by our payment provider, Stripe. Your full card number goes directly to Stripe; we never see or store it.</li><li><strong>Messages</strong> — anything you send us via the contact form or email, so we can help you.</li><li><strong>Newsletter signup</strong> — your email address, only if you choose to join. Unsubscribe anytime with one click.</li><li><strong>Site data</strong> — your shopping bag is saved in your own browser (local storage) so it persists between visits. We count page views and visits with Cloudflare Web Analytics, which uses no cookies and does not track individual visitors. We don't use advertising trackers.</li></ul><h2>How we use it</h2><p>To process and deliver your orders, respond to your messages, send newsletters you've opted into, and improve the store. That's it.</p><h2>What we never do</h2><p>We never sell, rent, or trade your personal information. We share order details only with the parties needed to fulfill your purchase: our payment processor (Stripe), our production/fulfillment partners, and the shipping carrier.</p><h2>Cookies and local storage</h2><p>We do not use advertising or analytics trackers. The site stores your shopping bag in your own browser's local storage so it persists between visits — this is not a cookie and is never sent to us. When you check out, you are taken to Stripe's secure checkout page, which may set its own cookies under Stripe's cookie policy. Our contact and newsletter forms are handled by FormSubmit; see our <a class="text-link" href="${BASE}/cookie-policy">cookie policy</a> for details.</p><h2>Your rights</h2><p>You can ask us at any time to see, correct, or delete the personal information we hold about you — email chikadibia17@gmail.com and we'll respond within 30 days. California residents: we honor CCPA requests the same way.</p><h2>Children's privacy</h2><p>Our store is intended for adults. We do not knowingly collect personal information from children under 13.</p><h2>Changes to this policy</h2><p>If we update this policy, we'll post the new version here with a new "last updated" date.</p></article>`}

function cookiePolicy(){return pageHero('LEGAL','Cookie policy','Last updated: September 29, 2026. Kadibia ("we", "us"). Contact: chikadibia17@gmail.com.')+`<article class="content"><h2>Do we use cookies?</h2><p>We do not set advertising cookies, and we do not run a cookie banner because there is nothing cookie-based to consent to. Your shopping bag is saved with your browser's local storage (not a cookie) and stays on your device. We do count page views and visits with Cloudflare Web Analytics, which is cookie-free and does not track individual visitors.</p><h2>Third parties</h2><ul><li><strong>Cloudflare Web Analytics:</strong> counts page views and visits without cookies and without tracking individual visitors.</li><li><strong>Stripe checkout:</strong> when you click "Buy now", you go to Stripe's secure checkout page. Stripe may set its own cookies there under <a class="text-link" href="https://stripe.com/cookies-policy/legal" target="_blank" rel="noopener">Stripe's cookie policy</a>.</li><li><strong>FormSubmit:</strong> our contact and newsletter forms are processed by FormSubmit, which delivers your message to us by email. FormSubmit's handling of form data is covered by its own privacy terms.</li></ul><h2>Your choices</h2><p>You can clear your browser's local storage at any time to empty your saved bag. Because we set no tracking cookies ourselves, there is no Kadibia cookie preference to manage.</p><h2>Questions</h2><p>Email chikadibia17@gmail.com — see also our <a class="text-link" href="${BASE}/privacy">privacy policy</a>.</p></article>`}

function terms(){return pageHero('LEGAL','Terms of service','Last updated: September 29, 2026. Kadibia ("we", "us"). Contact: chikadibia17@gmail.com.')+`<article class="content"><h2>Agreement</h2><p>By using this website and placing an order, you agree to these terms. If you don't agree, please don't use the site.</p><h2>Business details</h2><p><strong>Business name:</strong> Kadibia<br><strong>Address:</strong> 1212 Silliman Ave, Erie, PA, USA<br><strong>Contact:</strong> chikadibia17@gmail.com<br><strong>Where we sell:</strong> United States only.</p><h2>Products &amp; pricing</h2><p>We work hard to describe every product accurately, but slight variations in color or appearance can occur. All prices are in US dollars and may change without notice — the price at the moment you complete checkout is the price you pay.</p><h2>Orders &amp; payment</h2><p>Placing items in your bag doesn't reserve them. Your order is confirmed when payment is successfully processed through our secure checkout provider, Stripe. We reserve the right to cancel any order (for example, if a product becomes unavailable) — if that happens, you'll receive a full refund and we'll let you know promptly.</p><h2>Shipping &amp; returns</h2><p>Delivery times, shipping costs, and return terms are described in our <a class="text-link" href="${BASE}/shipping-returns">shipping &amp; returns policy</a>, which forms part of these terms.</p><h2>Intellectual property</h2><p>Everything on this site — text, design, logos, and images — belongs to Kadibia or its partners and may not be copied or reused without permission.</p><h2>Limitation of liability</h2><p>To the fullest extent permitted by law, Kadibia is not liable for indirect or consequential damages arising from your use of the site or products. Our total liability for any claim is limited to the amount you paid for the product in question.</p><h2>Governing law</h2><p>These terms are governed by the laws of the United States and of the state in which Kadibia operates, without regard to conflict-of-law principles.</p><h2>Contact</h2><p>Questions about these terms? Reach us at chikadibia17@gmail.com or via our <a class="text-link" href="${BASE}/contact">contact page</a>.</p></article>`}

function contact(){return pageHero('GET IN TOUCH','We’re here to help','Questions about an order, a product, or anything else? Send us a note — a real human replies within 2 business days.')+`<div class="content contact-grid"><div><h2>Say hello</h2><!-- REPLACE: your contact email --><p>Email: <a class="text-link" href="mailto:chikadibia17@gmail.com">chikadibia17@gmail.com</a></p><p>Support hours: Monday–Friday, 9am–5pm US Central</p><h2>Quick answers</h2><p>Order taking a while? Most orders arrive within 7–15 business days — check your tracking email first, then reach out if it's been longer.</p></div><!-- ============================================================
     CONTACT FORM — free setup:
     1. Go to https://formspree.io and create a free account + form.
     2. Paste your endpoint URL (https://formspree.io/f/xxxx) into the
        action="" attribute below (keep method="POST").
     3. Every submission lands in your inbox. Until a real URL is pasted,
        the form shows a friendly "not connected yet" message.
     ============================================================ --><form id="contact-form" action="https://formsubmit.co/chikadibia17@gmail.com" method="POST"><label class="field">Name<input name="name" required></label><label class="field">Email<input name="email" type="email" required></label><label class="field">Order number (if any)<input name="order"></label><label class="field">Message<textarea name="message" required></textarea></label><button class="btn" type="submit">Send message</button></form></div>`}

/* ------------------------------ CART & CHECKOUT ------------------------- */
function itemMarkup(i,index){let p=products.find(p=>p.id===i.id);if(!p)return '';return `<div class="cart-item"><a href="${BASE}/product/${p.id}"><img src="${p.images[0]}" alt="${esc(p.name)}"></a><div><h3><a href="${BASE}/product/${p.id}">${esc(p.name)}</a></h3><p>${esc(i.color)} / ${esc(i.size)}</p><div class="stepper"><button data-cart-qty="${index}" data-delta="-1" aria-label="Decrease ${esc(p.name)} quantity">−</button><span>${i.qty}</span><button data-cart-qty="${index}" data-delta="1" aria-label="Increase ${esc(p.name)} quantity">+</button></div><button class="link" data-remove="${index}">Remove</button></div><strong>${money(p.price*i.qty)}</strong></div>`}
function summary(){return `<div class="summary-line"><span>Subtotal</span><strong>${money(subtotal())}</strong></div><div class="summary-line"><span>Shipping</span><span>Free</span></div><small>US shipping is free on every order.</small>`}
function cartPage(){return pageHero('YOUR BAG','Shopping bag','Your picks are saved in this browser — they\'ll be here when you come back.')+`<section class="content cart-page" id="cart-page-content"></section>`}
function updateCart(){let n=count();$('#cart-count').textContent=n;$('#drawer-count').textContent=`(${n})`;$('#drawer-body').innerHTML=n?cart.map(itemMarkup).join(''):`<div class="empty"><h2>Your bag is empty</h2><p>Find something good in the collection.</p><a class="btn" href="${BASE}/shop">Browse products</a></div>`;$('#drawer-foot').innerHTML=n?`${summary()}<a class="btn full" href="${BASE}/checkout">Continue to checkout</a><a class="text-link" href="${BASE}/cart" style="display:block;text-align:center;margin-top:15px">View bag</a>`:'';if($('#cart-page-content'))$('#cart-page-content').innerHTML=n?`${cart.map(itemMarkup).join('')}<div class="cart-summary">${summary()}<a class="btn full" href="${BASE}/checkout">Continue to checkout</a></div>`:`<div class="empty"><h2>Your bag is empty</h2><p>Your next favorite is waiting.</p><a class="btn" href="${BASE}/shop">Shop products</a></div>`}
function checkoutItem(i){let p=products.find(p=>p.id===i.id);if(!p)return '';return `<div class="cart-item"><a href="${BASE}/product/${p.id}"><img src="${p.images[0]}" alt="${esc(p.name)}"></a><div><h3>${esc(p.name)}</h3><p>${esc(i.color)} / ${esc(i.size)} · Qty ${i.qty}</p>${stripeSetupDone(p.id)?'<a class="btn" href="'+buyLink(p.id)+'" target="_blank" rel="noopener">Buy now — '+money(p.price*i.qty)+'</a>':'<span class="btn" aria-disabled="true" style="opacity:.55">Available soon</span>'}</div><strong>${money(p.price*i.qty)}</strong></div>`}
function checkout(){return pageHero('SECURE CHECKOUT','Checkout','Pay safely with Stripe — no account needed.')+`<section class="content"><div class="notice"><strong>How checkout works:</strong> press <strong>Buy now</strong> under each item to complete your purchase on Stripe's secure checkout page (opens in a new tab). Your card details go directly to Stripe — Kadibia never sees or stores them.</div><div id="checkout-items"></div><div class="cart-summary" style="max-width:420px;margin:30px 0 0 auto">${summary()}<div style="margin-top:15px"><a class="text-link" href="${BASE}/shop">Keep shopping</a></div></div></section>`}
function renderCheckoutItems(){let el=$('#checkout-items');if(!el)return;el.innerHTML=cart.length?cart.map(checkoutItem).join(''):`<div class="empty"><h2>Your bag is empty</h2><p>Add something you love first.</p><a class="btn" href="${BASE}/shop">Shop products</a></div>`}

/* --------------------------------- ROUTER ------------------------------- */
function setTitle(title,desc){document.title=title+' | Kadibia';document.querySelector('meta[name="description"]').content=desc||'Kadibia — seamless activewear that moves with you. Comfort, quality, and fair prices.'}
const BASE='/kadibia-site-';
/* ---------- Launch-readiness helpers: consent wording, cookie-policy link, skip link ---------- */
function enhancePage(){
  // Skip link for keyboard users (added once).
  if(!document.querySelector('.skip-link')){
    let skip=document.createElement('a');
    skip.className='skip-link';skip.href='#app';skip.textContent='Skip to content';
    document.body.insertBefore(skip,document.body.firstChild);
  }
  // Cookie policy link in every footer Help section (added once per footer).
  document.querySelectorAll('footer a[href$="/terms"]').forEach(a=>{
    if(!a.parentElement.querySelector('a[href$="/cookie-policy"]')){
      let link=document.createElement('a');
      link.href=BASE+'/cookie-policy';link.textContent='Cookie policy';
      a.insertAdjacentElement('afterend',link);
    }
  });
  // Consent wording on newsletter forms.
  document.querySelectorAll('form.newsletter').forEach(f=>{
    if(!f.querySelector('.consent')){
      let s=document.createElement('small');
      s.className='consent';
      s.innerHTML='By joining, you agree to our <a class="text-link" href="'+BASE+'/privacy">privacy policy</a>.';
      f.insertAdjacentElement('afterend',s);
    }
  });
  // Consent wording on the contact form.
  let cf=document.getElementById('contact-form');
  if(cf&&!cf.querySelector('.consent')){
    let s=document.createElement('small');
    s.className='consent';
    s.innerHTML='By sending this message, you agree to our <a class="text-link" href="'+BASE+'/privacy">privacy policy</a>. We only use your details to reply.';
    let btn=cf.querySelector('button[type="submit"]');
    if(btn)btn.insertAdjacentElement('beforebegin',s);else cf.appendChild(s);
  }
}
function route(){let path=decodeURI(location.pathname).replace(/\/$/,'')||'/';if(path===BASE||path.indexOf(BASE+'/')===0){path=path.slice(BASE.length)||'/';}let html='',title='Seamless activewear';if(path==='/'){html=home()}else if(path==='/shop'){title='Shop all';html=shop()}else if(path.startsWith('/product/')){let p=products.find(x=>x.id===path.split('/')[2]);if(p){title=p.name;html=productPage(p)}else{title='Product not found';html=pageHero('OOPS','Product not found')+'<div class="content"><a class="btn" href="${BASE}/shop">Shop all</a></div>'}}else if(path==='/cart'){title='Shopping bag';html=cartPage()}else if(path==='/checkout'){title='Checkout';html=checkout()}else if(path==='/about'){title='Our story';html=about()}else if(path==='/contact'){title='Contact';html=contact()}else if(path==='/faq'){title='FAQ';html=faq()}else if(path==='/shipping-returns'){title='Shipping & returns';html=shipping()}else if(path==='/privacy'){title='Privacy policy';html=privacy()}else if(path==='/terms'){title='Terms of service';html=terms()}else if(path==='/cookie-policy'){title='Cookie policy';html=cookiePolicy()}else{title='Page not found';html=pageHero('OOPS','Page not found')+'<div class="content"><a class="btn" href="${BASE}/">Back home</a></div>'}$('#app').innerHTML=html;setTitle(title);enhancePage();if(path==='/shop'){$('#shop-sort').value=shopState.sort;renderShopResults()}if(path==='/checkout'){renderCheckoutItems()}updateCart();window.scrollTo(0,0);closeCart();$('.nav').classList.remove('open')}
function openCart(){$('#overlay').hidden=false;$('#cart-drawer').classList.add('open');$('#cart-drawer').setAttribute('aria-hidden','false');$('#cart-close').focus()}function closeCart(){$('#overlay').hidden=true;$('#cart-drawer').classList.remove('open');$('#cart-drawer').setAttribute('aria-hidden','true')}let toastTimer;function toast(message){let el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3000)}
document.addEventListener('click',e=>{let link=e.target.closest('a[href^="/"]');if(link){e.preventDefault();history.pushState({},'',link.getAttribute('href'));route();return}let filter=e.target.closest('[data-filter]');if(filter){shopState.category=filter.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===filter));renderShopResults()}let option=e.target.closest('[data-option]');if(option){selection[option.dataset.option]=option.dataset.value;option.parentElement.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===option));$('#selected-'+option.dataset.option).textContent=option.dataset.value}let thumb=e.target.closest('[data-image]');if(thumb){let gal=thumb.closest('[data-gallery]');let p=gal&&products.find(x=>x.id===gal.dataset.gallery);if(p){let mi=$('#main-image');if(mi)mi.src=p.images[Number(thumb.dataset.image)];let gm=gal.querySelector('.gallery-main');if(gm)gm.classList.remove('zoom');thumb.parentElement.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===thumb))}}let qty=e.target.closest('[data-product-qty]');if(qty){selection.quantity=Math.max(1,selection.quantity+Number(qty.dataset.productQty));$('#product-qty').textContent=selection.quantity}if(e.target.id==='add-to-cart')addItem(e.target.dataset.id,selection.color,selection.size,selection.quantity);let cq=e.target.closest('[data-cart-qty]');if(cq){let i=Number(cq.dataset.cartQty);cart[i].qty+=Number(cq.dataset.delta);if(cart[i].qty<=0)cart.splice(i,1);saveCart()}let rm=e.target.closest('[data-remove]');if(rm){cart.splice(Number(rm.dataset.remove),1);saveCart()}});document.addEventListener('input',e=>{if(e.target.id==='shop-search'){shopState.query=e.target.value;renderShopResults()}});document.addEventListener('change',e=>{if(e.target.id==='shop-sort'){shopState.sort=e.target.value;renderShopResults()}});
document.addEventListener('submit',e=>{
  let id=e.target.id;
  if(id==='home-newsletter'||id==='footer-newsletter'||id==='contact-form'){
    let action=e.target.getAttribute('action')||'';
    if(action.indexOf('REPLACE_ME')!==-1){
      // No real endpoint configured yet — don't submit anywhere.
      e.preventDefault();
      toast(id==='contact-form'?'Message service not connected yet — email us directly for now.':'Newsletter signup isn\'t connected yet — check back soon!');
    } else {
      // Real endpoint configured: let the browser submit normally.
      toast(id==='contact-form'?'Sending your message…':'Thanks for joining!');
    }
  }
});
$('#cart-toggle').onclick=openCart;$('#cart-close').onclick=closeCart;$('#overlay').onclick=closeCart;$('#menu-toggle').onclick=()=>$('.nav').classList.toggle('open');$('#search-toggle').onclick=()=>{history.pushState({},'',BASE+'/shop');route();$('#shop-search').focus()};document.addEventListener('keydown',e=>{if(e.key==='Escape')closeCart()});window.addEventListener('popstate',route);$('#year').textContent=new Date().getFullYear();initAnalytics();route();

/* Hover magnifier on the product main image (desktop): the zoom follows the cursor. */
if(window.matchMedia('(hover:hover)').matches){document.addEventListener('mousemove',e=>{let gm=e.target&&e.target.closest?e.target.closest('.gallery-main'):null;document.querySelectorAll('.gallery-main.zoom').forEach(x=>{if(x!==gm)x.classList.remove('zoom')});if(gm){let r=gm.getBoundingClientRect(),img=gm.querySelector('img');if(img)img.style.transformOrigin=((e.clientX-r.left)/r.width*100).toFixed(1)+'% '+((e.clientY-r.top)/r.height*100).toFixed(1)+'%';gm.classList.add('zoom')}});document.addEventListener('mouseout',e=>{let gm=e.target&&e.target.closest?e.target.closest('.gallery-main'):null;if(gm&&!(e.relatedTarget&&gm.contains(e.relatedTarget)))gm.classList.remove('zoom')});}
